'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(input[0]);
const p = input[1];

const prefix = Array.from({ length: 26 }, () => new Int32Array(n + 1));
const counts = new Int32Array(26);

for (let i = 0; i < n; i++) {
  counts[p.charCodeAt(i) - 97]++;
  for (let c = 0; c < 26; c++) {
    prefix[c][i + 1] = counts[c];
  }
}

let answer = '*';

for (let k = 1; k <= Math.floor(n / 2); k++) {
  if (n % k !== 0) continue;

  const blocks = n / k;
  let valid = true;

  for (let b = 1; b < blocks && valid; b++) {
    const start = b * k;
    const end = start + k;

    for (let c = 0; c < 26; c++) {
      if (prefix[c][end] - prefix[c][start] !== prefix[c][k]) {
        valid = false;
        break;
      }
    }
  }

  if (valid) {
    answer = p.slice(0, k);
    break;
  }
}

console.log(answer);
